export const careerCatalog=Object.fromEntries(Object.entries(catalogs).map(([code,groups])=>[code,groups.map(([title,names,reason])=>({title,reason,freelance:title==='自由探索',jobs:names.split('、')}))]));
const typeNames={R:'动手实践',I:'分析研究',A:'创作表达',S:'帮助他人',E:'组织推动',C:'整理执行'};
export function careerMarkup(code){
 const groups=careerCatalog[code]||[],salaryRows=salariesForRole(code);
 const listed=new Set([...groups.flatMap(g=>g.jobs),...salaryRows.map(r=>r.name)]);
 return `<section class="career-panel" id="careers"><div class="panel-heading"><span class="section-number">01</span><h2>你可以探索的职业与薪资</h2></div><p class="panel-intro">${listed.size} 个职业方向，从你的两类兴趣出发。以下 6 个岗位有可核验的招聘薪资样本，更多职业列在下方。</p><p class="salary-context">全国招聘样本 · 不限经验 · 人民币 / 月<br>区间为公开样本的集中分布，并非平均工资、应届起薪或个人收入预测。</p><div class="salary-grid">${salaryRows.map(row=>`<article class="salary-card"><span class="salary-type">关联兴趣 · ${typeNames[row.type]}</span><h3>${row.name}</h3><div class="salary-value">${row.low}–${row.high}K<small>/ 月</small></div><p>${row.share}% 的招聘样本位于此区间</p><details><summary>统计日期与来源</summary><p>近一年 · ${row.samples.toLocaleString('zh-CN')} 份样本<br>截至 ${row.asOf}<br><a href="${row.url}" target="_blank" rel="noreferrer">职友集公开薪酬统计 ↗</a></p></details></article>`).join('')}</div><h3>更多适合了解的职业</h3><div class="career-groups">${groups.map(g=>`<details class="career-group" open><summary>${g.title}<span>${g.jobs.length} 个方向</span></summary><p>${g.reason}</p><ul>${g.jobs.map(job=>`<li><span>${job}</span>${g.freelance?'<small>按项目或服务计费，不列固定月薪</small>':''}</li>`).join('')}</ul></details>`).join('')}</div><p class="career-disclaimer">这些数据来源于职业求职软件，仅供参考。经公开招聘数据统计平台汇总；全国样本混合了城市、行业和经验层次，招聘报价不等于到手工资。自由职业收入随项目、成本与合作方式变化。</p><details class="salary-note"><summary>如何理解职业建议与薪资？</summary><p>职业方向由本站根据兴趣活动整理，不是官方职业匹配结论。请结合技能、学历和经历选择；医疗、教育等岗位需满足相应资质。两种测试版本使用同一职业与薪资资料。</p><p>已核验的岗位直接展示薪资，其余探索方向暂不列数字。统计反映各来源注明日期之前一年的公开招聘样本，不是历年连续趋势。税前税后、奖金、提成和发薪月数须以具体岗位约定为准。数据核对日期：2026-09-13。</p></details><p class="career-disclaimer">这个结果仅供参考，不代表任职资格、录用机会或收入承诺。</p></section>`;
}
